import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"模块边界","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/module-boundaries","contentType":"concept","prev":{"text":"项目结构","link":"/architecture/project-structure"},"next":false},"headers":[],"relativePath":"architecture/module-boundaries.md","filePath":"architecture/module-boundaries.md"}'),o={name:"architecture/module-boundaries.md"};function n(d,a,l,i,b,c){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="模块边界" tabindex="-1">模块边界 <a class="header-anchor" href="#模块边界" aria-label="Permalink to &quot;模块边界&quot;">​</a></h1><p>Lab Word 复用现有 Core 与 Platform，并为实验室业务保留独立职责。相关目标来自 <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/adr/0003-static-example-composition.md" target="_blank" rel="noreferrer">ADR 0003</a>与 <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>。</p><h2 id="依赖关系" tabindex="-1">依赖关系 <a class="header-anchor" href="#依赖关系" aria-label="Permalink to &quot;依赖关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用入口 ──组合──&gt; 通用壳 + 业务贡献</span></span>
<span class="line"><span>业务 Views ─────&gt; SDK / Core / UI</span></span>
<span class="line"><span>SDK ────────────&gt; Contracts</span></span>
<span class="line"><span>业务 Application ──&gt; Core 公共能力 / Platform</span></span>
<span class="line"><span>Platform ───────&gt; 基础设施</span></span></code></pre></div><p>应用入口决定实际装配，Core 和通用壳保持不导入具体业务。Platform 不依赖 Application。当前知识库为参考业务；Lab 的三维资产与设备概念留在 Lab 自身。</p><h2 id="当前公开接口" tabindex="-1">当前公开接口 <a class="header-anchor" href="#当前公开接口" aria-label="Permalink to &quot;当前公开接口&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">组装合同</a>定义业务的页面、导航、文案和默认入口。<a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/packages/views/src/shell/app-contract.ts" target="_blank" rel="noreferrer">组装实现</a>拒绝重复 id、冲突路由、保留路由与缺失翻译。TanStack Router 留在 Web 适配层。</p><p>后端由 <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/apps/api/src/lib.rs" target="_blank" rel="noreferrer">API 入口</a>组合 Router 与 OpenAPI。Rust 模块的 <code>module.json</code> 声明表归属，模块通过公共能力协作，不直接读写其他模块的表。业务用例拥有事务边界；审计与任务在需要原子提交时使用同一个连接。</p><h2 id="验证和限制" tabindex="-1">验证和限制 <a class="header-anchor" href="#验证和限制" aria-label="Permalink to &quot;验证和限制&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>静态检查可以拒绝已知依赖与表归属越界，不能证明动态 SQL、真实授权或事务恢复正确。这些行为从 HTTP 和公开能力检查；阅读<a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/testing/strategy.md" target="_blank" rel="noreferrer">测试策略</a>。</p><p>“独立业务”表示源码和职责边界，不表示新的企业或租户。当前沿用<a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">单企业部署</a>。历史模板的完整所有权清单与删例工具在此副本中并不存在，不把目标架构视为已完成的命令。</p><p>Lab 的 <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/crates/app/src/modules/lab/module.json" target="_blank" rel="noreferrer">ownership</a> 以 <code>sdkPaths</code> 精确登记订阅 helper，以 <code>assemblyPoints</code> 登记 SDK facade 接入位置，<code>contractSymbols</code> 包含相应导出。移除 Lab 时一并移除这些 helper、测试、教程及 facade 的 Lab 导出，随后重新生成合同和 SDK；共享 HTTP/SSE 生命周期仍属于 SDK。边界检查仅允许已登记的业务 SDK 文件导入该业务合同，未登记 SDK 文件与 Core 仍受原规则约束。</p><p>后续 Lab 的导入失败、资源释放、快速切换与懒加载在正式应用验收，见<a href="./lab-word">产品范围</a>。</p><hr><p>源码版本：<code>a455a4dba0f3</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a455a4dba0f38691c8927d65d68695c8b6bbd0db/docs/architecture/module-boundaries.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,16)])])}const u=e(o,[["render",n]]);export{h as __pageData,u as default};
